const $=x=>document.getElementById(x),T={home:'Assessment overview',setup:'New assessment',interview:'Adaptive interview',graph:'Knowledge graph',report:'Assessment report',history:'Session history'};let S,cur,graphFilter=null,graphSelection=null,reportTab='overview',reportDomainFilter='all',reportEvidenceFilter='all',reportSearch='',historyTab='sessions',selectedHistoryId=null;const clamp=x=>Math.max(.05,Math.min(.95,x));
const DOMAIN_INFO={'Java':'Core language, collections, errors, and concurrency','Python':'Language features, iteration, and async programming','SQL':'Joins, transactions, indexes, and analytical queries','DSA':'Data structures, graphs, and complexity','Web Development':'Browser behavior, accessibility, React, and layout','System Design':'Scaling, caching, APIs, consistency, and messaging','Cloud & DevOps':'Containers, delivery, Kubernetes, and observability','Data Science & ML':'Model evaluation, leakage, and feature pipelines'};
const ROLE_DOMAINS={'Backend Engineer':['Java','Python','SQL','DSA','System Design','Cloud & DevOps'],'Frontend Engineer':['Web Development','DSA','System Design'],'Full-stack Engineer':['Java','Python','SQL','DSA','Web Development','System Design'],'Data Engineer':['Python','SQL','DSA','Cloud & DevOps','Data Science & ML','System Design'],'AI/ML Engineer':['Python','SQL','Data Science & ML','System Design'],'Cloud / DevOps Engineer':['Python','SQL','Cloud & DevOps','System Design'],'Graduate Developer':['Java','Python','SQL','DSA','Web Development']};
function go(id){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===id));$('pageTitle').textContent=T[id];if(id==='report')report();if(id==='history')history();if(id==='graph')graph()}
function toast(x){$('toast').textContent=x;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200)}
function containsConcept(answer,concept){if(concept.toLowerCase()==='map')return/\bmap\b|\bhashmap\b/i.test(answer);let escaped=concept.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return new RegExp('(^|[^a-z0-9])'+escaped+'($|[^a-z0-9])','i').test(answer)}
function profile(t){let terms={'Java':['java','spring'],'Python':['python'],'SQL':['sql','postgresql','mysql','database'],'DSA':['dsa','data structures','algorithms'],'Web Development':['web development','frontend','front end','javascript','react','html','css'],'System Design':['system design','architecture','microservices','scalable'],'Cloud & DevOps':['cloud','aws','azure','docker','kubernetes','devops','ci/cd'],'Data Science & ML':['data science','machine learning','pandas','scikit-learn']},r={};Object.entries(terms).forEach(([skill,words])=>{let n=words.reduce((total,word)=>total+(t.match(new RegExp(word,'gi'))||[]).length,0);if(n)r[skill]=Math.min(.65,.3+n*.08)});return r}
function selectedDomains(){return[...document.querySelectorAll('.domain-choice:checked')].map(x=>x.value)}
function updatePracticeSetup(){let domains=selectedDomains(),count=Q.filter(q=>domains.includes(q.skill)).length,questionCount=Math.min(12,count);let stats=document.querySelectorAll('.prep-card .session-stats b');if(stats[1])stats[1].textContent=`Up to ${questionCount} questions`;let small=document.querySelectorAll('.prep-card .session-stats small');if(small[1])small[1].textContent=`Across ${domains.length} selected domains`;let tags=document.querySelector('.prep-card .focus-tags');if(tags)tags.innerHTML=domains.map(d=>`<span>${d}</span>`).join('')||'<small>Select a domain to begin</small>';let picker=document.querySelector('.domain-picker');if(picker){let all=domains.length===Object.keys(DOMAIN_INFO).length;let toggle=picker.parentElement.querySelector('#toggleDomains');if(toggle)toggle.textContent=all?'Clear all':'Select all'} }
function setupDomains(){let form=document.querySelector('.form-panel'),actions=form.querySelector('.form-actions'),roleSelect=$('role'),wrap=document.createElement('section');Object.keys(ROLE_DOMAINS).forEach(role=>{if(![...roleSelect.options].some(option=>option.value===role)){let option=document.createElement('option');option.value=role;option.textContent=role;roleSelect.append(option)}});wrap.className='domain-picker-wrap';wrap.innerHTML=`<div class="domain-picker-head"><div><b>Choose practice domains</b><p class="sub">Build a focused round from one or more areas.</p></div><button class="text-link" id="toggleDomains" type="button">Select all</button></div><div class="domain-picker">${Object.entries(DOMAIN_INFO).map(([name,description])=>`<label class="domain-choice-card"><input class="domain-choice" type="checkbox" value="${name}" ${ROLE_DOMAINS[$('role').value].includes(name)?'checked':''}><span><b>${name}</b><small>${description}</small><em>${Q.filter(q=>q.skill===name).length} questions</em></span></label>`).join('')}</div>`;form.insertBefore(wrap,actions);wrap.querySelectorAll('.domain-choice').forEach(el=>el.addEventListener('change',updatePracticeSetup));wrap.querySelector('#toggleDomains').onclick=()=>{let choices=[...wrap.querySelectorAll('.domain-choice')],select=choices.some(x=>!x.checked);choices.forEach(x=>x.checked=select);updatePracticeSetup()};$('role').addEventListener('change',()=>{let chosen=ROLE_DOMAINS[$('role').value]||[];wrap.querySelectorAll('.domain-choice').forEach(x=>x.checked=chosen.includes(x.value));updatePracticeSetup()});updatePracticeSetup()}
function renderAtlas(){let metrics=document.querySelector('#home .metrics'),section=document.createElement('section');section.className='panel domain-atlas';section.innerHTML=`<div class="section-head"><div><p class="eyebrow">PRACTICE LIBRARY</p><h2>Explore the domains</h2></div><button class="text-link" id="atlasStart">Choose a practice set →</button></div><div class="domain-atlas-grid">${Object.entries(DOMAIN_INFO).map(([name,description])=>`<button class="domain-card" data-domain="${name}"><span class="domain-card-icon">${name==='Data Science & ML'?'◈':name==='Cloud & DevOps'?'⌘':name==='System Design'?'◇':name==='Web Development'?'▧':'⌑'}</span><b>${name}</b><small>${Q.filter(q=>q.skill===name).length} questions</small><p>${description}</p></button>`).join('')}</div>`;metrics.after(section);section.querySelector('#atlasStart').onclick=()=>go('setup');section.querySelectorAll('.domain-card').forEach(card=>card.onclick=()=>practiceDomain(card.dataset.domain));$('bankCount').textContent=Q.length}
function updateDashboard(){let articles=document.querySelectorAll('#home .metrics article'),sessions=storedHistory();if(articles[0]){articles[0].querySelector('b').textContent=Q.length;articles[0].querySelector('small').textContent=`questions across ${Object.keys(DOMAIN_INFO).length} domains`}if(articles[1]){articles[1].querySelector('span').textContent='Practice library';articles[1].querySelector('b').textContent=Object.keys(DOMAIN_INFO).length;articles[1].querySelector('small').textContent='role-based technical domains'}if(articles[2]){articles[2].querySelector('span').textContent='Saved sessions';articles[2].querySelector('b').textContent=sessions.length;articles[2].querySelector('small').textContent='stored in this browser'}}
function updateHomeCopy(){let hero=document.querySelector('#home .hero');hero.querySelector('h2').innerHTML='Practice across<br><em>real interview domains.</em>';hero.querySelector('p:not(.eyebrow)').textContent='Build confidence across software, data, web, cloud, and system design topics. Choose a focus, answer adaptive questions, and turn each session into a personal study plan.';$('launch').innerHTML='Choose a practice set <span>→</span>'}
function bars(){ $('competencies').innerHTML=Object.entries(S.c).map(([k,v])=>`<div class="bar"><div class="bar-top"><span>${k}</span><span>${Math.round(v*100)}%</span></div><div class="track"><i class="fill" style="width:${v*100}%"></i></div></div>`).join('')}
function next(){if(S.asked.length>=S.limit)return null;let left=S.questions.filter(q=>!S.asked.includes(q.id));if(!left.length)return null;return left.map(q=>{let c=S.c[q.skill]??.35,w=1-c,f=1-Math.abs(q.level/3-c);return{q,score:.65*w+.35*f,w,f}}).sort((a,b)=>b.score-a.score)[0]}
function updateCoach(skill){let tips={Java:['Explain the mechanism','Name the relevant data structure or language feature, then walk through how it behaves in a concrete example. Mention complexity or a trade-off when it helps.'],Python:['Explain the behavior','Describe what Python does step by step, then use a small example. Call out errors, iteration, or memory behavior where relevant.'],SQL:['Explain the result','Describe which rows are returned or changed, then walk through a small table example. Mention NULL behavior and performance trade-offs when relevant.'],DSA:['State the invariant','Explain the key idea, show how it changes on an example input, and give the time and space complexity.'], 'Web Development':['Trace the user journey','Explain what the browser or component does after an interaction. Include state, accessibility, and what the user sees next.'],'System Design':['Clarify constraints first','Start with scale and reliability needs. Sketch the request and data flow, then explain bottlenecks and failure trade-offs.'],'Cloud & DevOps':['Follow the release lifecycle','Explain how the service is built, deployed, observed, and recovered. Include one security or reliability safeguard.'],'Data Science & ML':['Start with the objective','Define the target and evaluation metric, describe the data split, then explain leakage risks and how you would validate results.']};let tip=tips[skill];$('coachTitle').textContent=tip?tip[0]:'A simple answer structure';$('coachTip').textContent=tip?tip[1]:'Start with the main idea. Explain how it works, give a real example, then mention one trade-off or edge case.'}
function load(keepFeedback=false){let n=next();if(!keepFeedback)$('feedback').classList.add('hidden');if(!n){cur=null;$('question').textContent='Practice complete — you have worked through your selected question set.';$('skill').textContent='Complete';$('difficulty').textContent='Report ready';$('whyTitle').textContent='What next?';$('reason').textContent='Review your evidence and choose one weak area to practice again.';$('submit').disabled=true;$('submit').textContent='Practice complete';$('state').textContent='Practice complete';$('progressText').textContent='QUESTION SET COMPLETE';$('progressBar').style.width='100%';return}cur=n;$('skill').textContent=n.q.skill;$('difficulty').textContent='Level '+n.q.level;$('question').textContent=n.q.question;$('whyTitle').textContent='Why this question?';$('reason').textContent=`Targets ${n.q.skill} at ${Math.round((S.c[n.q.skill]??.35)*100)}% confidence. This question best balances a skill gap with an achievable challenge.`;$('factors').innerHTML=`<div class="signal" title="Lower confidence increases priority"><span>Skill gap</span><b>${Math.round(n.w*100)}%</b></div><div class="signal" title="How well this question's difficulty matches current confidence"><span>Difficulty fit</span><b>${Math.round(n.f*100)}%</b></div><div class="signal" title="Combined estimate from skill gap and difficulty fit"><span>Information gain</span><b>${Math.round(n.score*100)}%</b></div><p class="signal-foot">Higher values indicate a stronger reason to ask this question now.</p>`;updateCoach(n.q.skill);$('answer').value='';$('submit').disabled=false;$('submit').textContent='Evaluate answer →';$('progressText').textContent=`QUESTION ${S.a.length+1} OF ${S.limit}`;$('progressBar').style.width=(S.a.length/S.limit*100)+'%'}
function start(){let name=$('name').value.trim(),domains=selectedDomains();if(!name)return toast('Enter your name to begin.');if(!domains.length)return toast('Choose at least one practice domain.');let detected=profile($('resume').value),questions=Q.filter(q=>domains.includes(q.skill));S={id:Date.now(),name,role:$('role').value,domains,questions,limit:Math.min(12,questions.length),c:Object.fromEntries(domains.map(skill=>[skill,detected[skill]??.35])),asked:[],a:[]};$('candidateLabel').textContent=name+"'s practice session";$('state').textContent='Interview active';$('interviewSetup').classList.add('hidden');bars();load();go('interview')}
function assess(){if(!cur)return;let answer=$('answer').value.trim(),text=answer.toLowerCase();if(!text)return toast('Enter an answer before evaluating.');let q=cur.q,d=q.concepts.filter(x=>containsConcept(text,x)),m=q.concepts.filter(x=>!d.includes(x)),score=d.length/q.concepts.length,before=S.c[q.skill]??.35,after=Math.round(clamp(before+.38*(1-before/2)*(score-before))*100)/100;S.c[q.skill]=after;S.asked.push(q.id);S.a.push({skill:q.skill,question:q.question,answer,score,d,m,before,after});bars();$('feedback').classList.remove('hidden');let followup=m.length?`Can you explain <b>${m[0]}</b> and connect it to a concrete example?`:'Can you give a real example and explain one trade-off?';$('feedback').innerHTML=`<div class="feedback-heading"><div><p class="eyebrow">PRACTICE FEEDBACK</p><h3>Concept coverage <span class="score">${Math.round(score*100)}%</span></h3></div><span class="feedback-note">Practice signal, not a complete answer grade</span></div><p><b>Concepts you touched:</b> ${d.length?d.map(x=>`<span class="chip">${x}</span>`).join(''):'No listed concepts detected yet'}</p><p><b>Consider adding:</b> ${m.length?m.map(x=>`<span class="chip warn">${x}</span>`).join(''):'A concrete example or trade-off'}</p><div class="followup-prompt"><b>Try this interviewer follow-up</b><p>${followup}</p></div><p class="sub">${q.skill} practice confidence moved from <b>${Math.round(before*100)}%</b> to <b>${Math.round(after*100)}%</b> based on concept coverage.</p>`;load(true)}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function storedHistory(){try{return JSON.parse(localStorage.getItem('inferiq')||'[]')}catch{return[]}}
function data(){let nodes=Object.entries(S.c).map(([skill,score])=>{let answers=S.a.filter(a=>a.skill===skill),concepts=[...new Set(Q.filter(q=>q.skill===skill).flatMap(q=>q.concepts))];return{skill,score,answered:answers.length,found:[...new Set(answers.flatMap(a=>a.d))],missing:[...new Set(answers.flatMap(a=>a.m))],conceptCount:concepts.length}}).sort((a,b)=>b.score-a.score),overall=Math.round(nodes.reduce((n,x)=>n+x.score,0)/Math.max(1,nodes.length)*100);return{nodes,overall,answered:S.a.length,limit:S.limit,domains:S.domains,coverage:Math.round(S.a.length/Math.max(1,S.limit)*100)}}
function ensureTabs(id,bodyId,items,current,setter){let nav=$(id);if(!nav){nav=document.createElement('div');nav.id=id;nav.className='page-tabs';$(bodyId).before(nav)}nav.innerHTML=items.map(([key,label])=>`<button class="page-tab ${current===key?'active':''}" data-tab="${key}">${label}</button>`).join('');nav.querySelectorAll('[data-tab]').forEach(btn=>btn.onclick=()=>{setter(btn.dataset.tab);id==='reportTabs'?report():history()})}
function saveCurrentReport(r){let h=storedHistory(),prior=h.find(x=>x.id===S.id),record={id:S.id,name:S.name,role:S.role,overall:r.overall,n:S.a.length,limit:S.limit,date:prior?.date||new Date().toISOString(),domains:S.domains,competencies:r.nodes,answers:S.a,completed:S.a.length>=S.limit};localStorage.setItem('inferiq',JSON.stringify([record,...h.filter(x=>x.id!==S.id)]));updateDashboard()}
function reportBase(){let body=$('reportBody');if(!S||!S.a.length){$('reportTabs')?.classList.add('hidden');body.className='empty panel';body.innerHTML='<h2>No practice report yet</h2><p>Complete a few questions to build a useful report and personal study plan.</p><button class="primary" data-go="setup">Start practicing</button>';return}let r=data(),weak=r.nodes.filter(x=>x.score<.5),strong=r.nodes.filter(x=>x.score>=.7),missing=[...new Set(S.a.flatMap(a=>a.m))];saveCurrentReport(r);ensureTabs('reportTabs','reportBody',[['overview','Overview'],['skills','Competencies'],['answers','Answer review'],['plan','Study plan']],reportTab,x=>reportTab=x);$('reportTabs').classList.remove('hidden');body.className='report-content';if(reportTab==='overview'){body.innerHTML=`<div class="report-hero"><p class="eyebrow">PRACTICE SUMMARY</p><h2>${esc(S.name)}</h2><p>${esc(S.role)} · ${S.domains.length} domains · ${S.a.length} of ${S.limit} questions</p><span class="score">${r.overall}%</span><p>Practice confidence estimate</p></div><div class="report-stat-grid"><article class="panel"><span>Questions practiced</span><b>${r.answered}/${r.limit}</b><small>${r.coverage}% of this round</small></article><article class="panel"><span>Domains covered</span><b>${new Set(S.a.map(a=>a.skill)).size}</b><small>of ${S.domains.length} selected</small></article><article class="panel"><span>Concept signals</span><b>${new Set(S.a.flatMap(a=>a.d)).size}</b><small>distinct concepts detected</small></article></div><div class="panel report-overview-grid"><div><p class="eyebrow">WHAT WENT WELL</p><h3>${strong.length?esc(strong.map(x=>x.skill).join(', ')):'Keep building evidence'}</h3><p class="sub">${strong.length?'These areas currently have the strongest practice confidence.':'Your confidence profile is still developing. Answer more questions to build a clearer picture.'}</p></div><div><p class="eyebrow">NEXT FOCUS</p><h3>${weak.length?esc(weak.map(x=>x.skill).join(', ')):'Stretch into a harder round'}</h3><p class="sub">${missing.length?`Concepts to revisit: ${esc(missing.slice(0,8).join(', '))}`:'Try a higher difficulty or explain a real-world example.'}</p></div></div><div class="report-actions"><button class="ghost" data-report-tab="answers">Review my answers</button><button class="ghost" data-report-tab="plan">Open study plan</button><button class="primary" id="download">Download full report</button></div>`}else if(reportTab==='skills'){body.innerHTML=`<div class="panel"><p class="eyebrow">DOMAIN BREAKDOWN</p><h2>Competency profile</h2><p class="sub">Confidence is updated from detected concept coverage and is a practice signal, not a validated score.</p>${r.nodes.map(x=>`<div class="skill-report-row"><div class="skill-report-heading"><b>${esc(x.skill)}</b><span>${Math.round(x.score*100)}% · ${x.score>=.7?'Strong signal':x.score>=.5?'Developing':'Practice focus'}</span></div><div class="track"><i class="fill" style="width:${x.score*100}%"></i></div><p class="sub">${x.answered} answers · ${x.found.length} concepts detected${x.missing.length?` · consider ${esc(x.missing.slice(0,5).join(', '))}`:''}</p></div>`).join('')}</div><div class="report-actions"><button class="ghost" data-go="graph">Open evidence graph</button></div>`}else if(reportTab==='answers'){body.innerHTML=`<div class="panel"><p class="eyebrow">ANSWER-BY-ANSWER REVIEW</p><h2>Your practice transcript</h2><p class="sub">Concept matching is lexical. Review the detected and suggested concepts as prompts for reflection, not a complete grading of your answer.</p>${S.a.map((a,i)=>`<article class="answer-review"><div class="answer-review-head"><span class="pill">${esc(a.skill)}</span><span>Question ${i+1} · ${Math.round(a.score*100)}% concept coverage</span></div><h3>${esc(a.question)}</h3><details><summary>Your answer</summary><p class="answer-text">${esc(a.answer||'No saved response.')}</p></details><p class="sub"><b>Detected:</b> ${esc(a.d.join(', ')||'none')}<br><b>Consider adding:</b> ${esc(a.m.join(', ')||'a concrete example or trade-off')}</p></article>`).join('')}</div>`}else{let focus=weak.length?weak:r.nodes.slice(-2),recommendations=focus.map(node=>{let concepts=[...new Set(S.a.filter(a=>a.skill===node.skill).flatMap(a=>a.m))];return{skill:node.skill,concepts,action:concepts.length?`Review ${concepts.slice(0,4).join(', ')}, then explain each concept in a concrete example.`:`Try one level-harder ${node.skill} question and talk through the trade-offs.`}});body.innerHTML=`<div class="panel"><p class="eyebrow">PERSONALIZED NEXT STEPS</p><h2>Your study plan</h2><p class="sub">Focus on one area at a time. Revisit the suggested concepts, then repeat a short practice round.</p><div class="study-plan">${recommendations.map((x,i)=>`<article class="study-step"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(x.skill)}</h3><p>${esc(x.action)}</p><button class="text-link" data-practice-domain="${esc(x.skill)}">Practice ${esc(x.skill)} →</button></div></article>`).join('')}</div></div>`}let download=$('download');if(download)download.onclick=()=>downloadReport(r);body.querySelectorAll('[data-report-tab]').forEach(btn=>btn.onclick=()=>{reportTab=btn.dataset.reportTab;report()});body.querySelectorAll('[data-practice-domain]').forEach(btn=>btn.onclick=()=>practiceDomain(btn.dataset.practiceDomain));body.querySelectorAll('[data-go="graph"]').forEach(btn=>btn.onclick=()=>go('graph'))}
function downloadReport(r=data()){let payload={candidate:S.name,role:S.role,domains:S.domains,summary:r,answers:S.a,generatedAt:new Date().toISOString()};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='inferiq-practice-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
