function reportEnhanceBase(){reportBase();if(!S||!S.a.length||reportTab!=='overview')return;let body=$('reportBody'),answeredBySkill=Object.fromEntries(S.domains.map(skill=>[skill,S.a.filter(a=>a.skill===skill)])),rows=Object.entries(answeredBySkill).map(([skill,answers])=>{let coverage=answers.length?Math.round(answers.reduce((n,a)=>n+a.score,0)/answers.length*100):0,detected=[...new Set(answers.flatMap(a=>a.d))],toReview=[...new Set(answers.flatMap(a=>a.m))];return`<article class="insight-row"><div class="insight-row-head"><b>${esc(skill)}</b><span>${answers.length?`${coverage}% concept coverage`:'Not yet practiced'}</span></div>${answers.length?`<div class="track"><i class="fill" style="width:${coverage}%"></i></div><p>${answers.length} answer${answers.length===1?'':'s'} · ${detected.length} concepts detected${toReview.length?` · revisit ${esc(toReview.slice(0,4).join(', '))}`:' · no listed concepts missed'}</p>`:'<p>Answer a question in this domain to add evidence to the report.</p>'}</article>`}).join(''),avg=Math.round(S.a.reduce((n,a)=>n+a.score,0)/S.a.length*100),best=S.a.reduce((a,b)=>a.score>=b.score?a:b),next=S.a.reduce((a,b)=>a.score<=b.score?a:b);body.insertAdjacentHTML('beforeend',`<section class="panel report-insights"><p class="eyebrow">ANSWER EVIDENCE</p><h2>How your answers performed</h2><p class="sub">Average concept coverage is ${avg}%. This measures mentions of the question bank's target concepts; it is a coaching signal, not an overall hiring or answer-quality score.</p><div class="insight-summary"><article><span>Strongest answer</span><b>${esc(best.skill)}</b><small>${Math.round(best.score*100)}% concept coverage</small></article><article><span>Best next review</span><b>${esc(next.skill)}</b><small>${Math.round(next.score*100)}% concept coverage</small></article><article><span>Evidence mapped</span><b>${new Set(S.a.flatMap(a=>a.d)).size}</b><small>distinct concepts detected</small></article></div><h3>Domain-by-domain signals</h3>${rows}</section><section class="panel report-guidance"><p class="eyebrow">HOW TO READ THIS REPORT</p><h3>Use the signals as practice guidance</h3><p class="sub">Concepts are detected with transparent keyword matching. A low coverage result may mean the answer used different wording, so review the answer transcript and judge the reasoning in context. Confidence is a local practice estimate and should not be used as a hiring decision.</p><button class="ghost" data-report-tab="answers">Review answer transcript</button> <button class="ghost" data-go="graph">Explore concept evidence</button></section>`);body.querySelectorAll('[data-report-tab]').forEach(btn=>btn.onclick=()=>{reportTab=btn.dataset.reportTab;report()});body.querySelectorAll('[data-go="graph"]').forEach(btn=>btn.onclick=()=>go('graph'))}
function graph(){let allSkills=[...new Set(Q.map(q=>q.skill))],skills=graphFilter?allSkills.filter(skill=>skill===graphFilter):allSkills;let cards=skills.map(skill=>{let concepts=[...new Set(Q.filter(q=>q.skill===skill).flatMap(q=>q.concepts))],confidence=S?.c[skill]??.35,found=concepts.filter(name=>conceptState(skill,name)==='evidenced').length;return`<article class="simple-skill-card"><button class="simple-skill-head" data-skill="${esc(skill)}"><span><b>${esc(skill)}</b><small>${found} of ${concepts.length} concepts evidenced · ${Q.filter(q=>q.skill===skill).length} questions</small></span><strong>${Math.round(confidence*100)}%</strong></button><div class="track"><i class="fill" style="width:${confidence*100}%"></i></div><div class="concept-list">${concepts.map(name=>{let state=conceptState(skill,name);return`<button class="concept-chip ${state==='evidenced'?'is-found':''} ${graphSelection?.skill===skill&&graphSelection?.concept===name?'is-selected':''}" data-skill="${esc(skill)}" data-concept="${esc(name)}" title="${state}"><i></i>${esc(name)}</button>`}).join('')}</div></article>`}).join('');$('graphCanvas').innerHTML=`<div class="simple-graph-grid">${cards}</div>`;$('graphCanvas').style.minHeight='0';$('graphCanvas').querySelectorAll('[data-skill]:not([data-concept])').forEach(button=>button.onclick=()=>{graphFilter=graphFilter===button.dataset.skill?null:button.dataset.skill;graphSelection={skill:button.dataset.skill,concept:null};graph()});$('graphCanvas').querySelectorAll('[data-concept]').forEach(button=>button.onclick=()=>{graphFilter=button.dataset.skill;graphSelection={skill:button.dataset.skill,concept:button.dataset.concept};graph();renderGraphDetails(button.dataset.skill,button.dataset.concept)});renderGraphDetails(graphSelection?.skill,graphSelection?.concept)}
function report(){reportEnhanceBase();if(!S||!S.a.length)return;let body=$('reportBody');if(reportTab==='overview'){body.querySelectorAll('.insight-row').forEach(row=>{let skill=row.querySelector('b')?.textContent;if(!skill||row.querySelector('[data-review-domain]'))return;row.insertAdjacentHTML('beforeend',`<button class="text-link report-domain-review" data-review-domain="${esc(skill)}">Review ${esc(skill)} answers →</button>`)});body.querySelectorAll('[data-review-domain]').forEach(button=>button.onclick=()=>{reportDomainFilter=button.dataset.reviewDomain;reportTab='answers';report()})}if(reportTab==='overview'){let misses=Object.entries(S.a.flatMap(a=>a.m).reduce((counts,concept)=>(counts[concept]=(counts[concept]||0)+1,counts),{})).sort((a,b)=>b[1]-a[1]).slice(0,6),focus=data().nodes.slice().sort((a,b)=>a.score-b.score).slice(0,3),weakAnswers=S.a.map((answer,index)=>({...answer,index})).sort((a,b)=>a.score-b.score).slice(0,3),plan=focus.map((node,index)=>`${index+1}. ${node.skill}: ${node.missing.length?`Review ${node.missing.slice(0,4).join(', ')}.`:`Answer a harder question and explain one trade-off.`}`).join('\n');body.insertAdjacentHTML('beforeend',`<section class="panel report-roadmap"><div class="roadmap-heading"><div><p class="eyebrow">PERSONALIZED ACTION PLAN</p><h2>Your next practice steps</h2><p class="sub">Use this short sequence to turn this session’s evidence into deliberate practice.</p></div><button class="ghost" id="downloadActionPlan">Download action list</button></div><div class="roadmap-steps"><article><span>01</span><div><b>Revisit recurring gaps</b><p>${misses.length?`Your most frequently missed concepts: ${misses.map(([name,count])=>`${esc(name)} (${count})`).join(' · ')}.`:'No target concepts were missed in the answers so far. Try a more challenging question to extend your evidence.'}</p></div></article><article><span>02</span><div><b>Practice your lowest-signal domain</b><p>${focus[0]?`${esc(focus[0].skill)} is currently at ${Math.round(focus[0].score*100)}% practice confidence. Review a missed concept, then answer aloud with an example and trade-off.`:'Complete another answer to build a domain signal.'}</p>${focus[0]?`<button class="text-link" data-plan-domain="${esc(focus[0].skill)}">Practice ${esc(focus[0].skill)} →</button>`:''}</div></article><article><span>03</span><div><b>Repeat and compare</b><p>Run another focused round after review. Compare the next report with this one to see whether concept coverage and confidence move together.</p><button class="text-link" data-go="setup">Start another round →</button></div></article></div></section><section class="panel report-missed"><p class="eyebrow">REPEATED REVIEW TOPICS</p><h2>Concepts to revisit</h2><p class="sub">Topics below were not detected in one or more responses. Check the transcript before drawing conclusions; different wording can express the same idea.</p>${misses.length?`<div class="missed-concept-list">${misses.map(([name,count])=>`<span class="missed-concept"><b>${esc(name)}</b><small>${count} response${count===1?'':'s'}</small></span>`).join('')}</div>`:'<p class="report-positive">No repeated concept gaps detected in this session.</p>'}</section><section class="panel report-review-shortlist"><p class="eyebrow">REVIEW SHORTLIST</p><h2>Answers worth a second look</h2><p class="sub">These answers had the lowest target-concept coverage in this session.</p>${weakAnswers.map(a=>`<article class="shortlist-row"><div><b>${esc(a.skill)} · ${Math.round(a.score*100)}% coverage</b><p>${esc(a.question)}</p><small>Detected: ${esc(a.d.join(', ')||'none')} · Consider: ${esc(a.m.slice(0,4).join(', ')||'add a concrete example')}</small></div><button class="ghost" data-review-answer="${a.index}">Open answer</button></article>`).join('')}</section><details class="panel report-score-guide"><summary>How to interpret these practice signals</summary><p class="sub">Concept coverage counts target phrases detected by the local prototype. Confidence is updated from that coverage, so it can miss equivalent wording and should not be treated as a validated interview grade or hiring recommendation. Use the saved answer, reasoning, examples, and trade-offs as the main review material.</p></details>`);body.querySelectorAll('[data-plan-domain]').forEach(button=>button.onclick=()=>practiceDomain(button.dataset.planDomain));body.querySelectorAll('[data-go="setup"]').forEach(button=>button.onclick=()=>go('setup'));body.querySelectorAll('[data-review-answer]').forEach(button=>button.onclick=()=>{let index=button.dataset.reviewAnswer;reportTab='answers';reportDomainFilter='all';reportEvidenceFilter='all';reportSearch='';report();let card=$(`reportBody`).querySelector(`.answer-review[data-answer-index="${index}"]`);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});card.querySelector('details')?.setAttribute('open','')}});let downloadPlan=$('downloadActionPlan');if(downloadPlan)downloadPlan.onclick=()=>{let text=`InferIQ practice action list\nCandidate: ${S.name}\nRole: ${S.role}\n\n${plan}\n\nPractice signals are coaching prompts, not a validated interview grade.`;let link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));link.download='inferiq-practice-action-list.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}}if(reportTab!=='answers')return;let panel=body.querySelector('.panel');if(!panel)return;let words=S.a.map(a=>(a.answer||'').trim().split(/\s+/).filter(Boolean).length),meanWords=Math.round(words.reduce((n,x)=>n+x,0)/Math.max(1,words.length)),missedCount=S.a.reduce((n,a)=>n+a.m.length,0);panel.insertAdjacentHTML('afterbegin',`<div class="answer-tools"><div><p class="eyebrow">TRANSCRIPT EXPLORER</p><h3>Find an answer to review</h3><p class="sub">${S.a.length} answers · ${meanWords} words per answer on average · ${missedCount} concept prompts to revisit</p></div><div class="answer-filter-controls"><label>Domain<select id="answerDomainFilter"><option value="all">All domains</option>${S.domains.map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('')}</select></label><label>Evidence<select id="answerEvidenceFilter"><option value="all">All evidence</option><option value="review">Needs review</option><option value="detected">Has detected concepts</option><option value="strong">High concept coverage (75%+)</option></select></label><label class="answer-search-label">Search<input id="answerSearch" type="search" placeholder="Question, answer, concept…"></label></div><p class="answer-result-count" id="answerResultCount" aria-live="polite"></p></div>`);let cards=[...panel.querySelectorAll('.answer-review')];cards.forEach((card,i)=>{let a=S.a[i];card.dataset.skill=a.skill;card.dataset.answerIndex=i;card.insertAdjacentHTML('beforeend',`<button class="text-link answer-practice" data-practice-domain="${esc(a.skill)}">Practice ${esc(a.skill)} again →</button>`)});let domain=$('answerDomainFilter'),evidence=$('answerEvidenceFilter'),search=$('answerSearch');domain.value=reportDomainFilter;evidence.value=reportEvidenceFilter;search.value=reportSearch;let filter=()=>{reportDomainFilter=domain.value;reportEvidenceFilter=evidence.value;reportSearch=search.value;let visible=0;cards.forEach((card,i)=>{let a=S.a[i],needle=reportSearch.toLowerCase(),haystack=[a.question,a.answer,...a.d,...a.m].join(' ').toLowerCase(),matchDomain=reportDomainFilter==='all'||a.skill===reportDomainFilter,matchEvidence=reportEvidenceFilter==='all'||reportEvidenceFilter==='review'&&a.m.length>0||reportEvidenceFilter==='detected'&&a.d.length>0||reportEvidenceFilter==='strong'&&a.score>=.75,show=matchDomain&&matchEvidence&&(!needle||haystack.includes(needle));card.classList.toggle('filtered-out',!show);if(show)visible++});$('answerResultCount').textContent=`Showing ${visible} of ${cards.length} answers`;let empty=panel.querySelector('.answer-filter-empty');if(!visible&&!empty){panel.insertAdjacentHTML('beforeend','<p class="answer-filter-empty sub">No answers match these filters. Try another domain or search term.</p>')}else if(visible&&empty)empty.remove()};domain.onchange=filter;evidence.onchange=filter;search.oninput=filter;filter();panel.querySelectorAll('[data-practice-domain]').forEach(button=>button.onclick=()=>practiceDomain(button.dataset.practiceDomain))}
